// sfb-ripmode-router — Cloudflare Worker.
// 1) Proxies sixfigureblueprints.com/ripmode* to the Vercel app (BillMe pattern).
// 2) Serves the app's API at /ripmode/api/* with shared state in KV (ripmode-data).
// Passwords are stored ONLY as salted PBKDF2-SHA256 hashes (100,000 iterations — the Cloudflare Workers PBKDF2 cap).
// Google Voice has NO API: this worker never dials, texts, or drops voicemail.
// The personal forwarding number must NEVER appear in this file or any response.

const UPSTREAM = "https://sfb-ripmode.vercel.app";
const ALLOWED_USERS = ["romanroyce", "loganwells", "braylengarrett"];
const SESSION_DAYS = 30;

const enc = new TextEncoder();
const dec = new TextDecoder();

function json(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      "Content-Type": "application/json",
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Headers": "Content-Type, Authorization",
      "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    },
  });
}
const err = (message, status = 400) => json({ error: message }, status);

function b64(buf) {
  const bytes = new Uint8Array(buf);
  let s = "";
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s);
}
function unb64(s) {
  const bin = atob(s);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}
function hex(buf) {
  return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
}
async function sha256Hex(text) {
  return hex(await crypto.subtle.digest("SHA-256", enc.encode(text)));
}
async function hashPassword(password, saltB64) {
  const salt = saltB64 ? unb64(saltB64) : crypto.getRandomValues(new Uint8Array(16));
  const key = await crypto.subtle.importKey("raw", enc.encode(password), "PBKDF2", false, ["deriveBits"]);
  const bits = await crypto.subtle.deriveBits(
    { name: "PBKDF2", salt, iterations: 100000, hash: "SHA-256" },
    key, 256
  );
  return { salt: b64(salt), hash: b64(bits) };
}

function seedState() {
  return {
    leads: [
      { id: "lead-jax", business: "Jax Roofing", niche: "Roofing", city: "Jacksonville", phone: "(904) 621-6005", owner: "", email: "", stage: "New" },
      { id: "lead-performance", business: "Performance Roofing", niche: "Roofing", city: "Oviedo", phone: "(407) 210-1503", owner: "", email: "info@performanceroofingusa.com", stage: "New" },
    ],
    callLogs: [],
    conversations: [],
    meetings: [],
    followUps: [],
    sessionStats: { dials: 0, connected: 0, noAnswer: 0, voicemail: 0, meetings: 0, perHour: 0 },
    scripts: [
      {
        title: "Roofer pitch",
        body: "Hi, this is Roman from SFB Connect — we build AI receptionists for roofers that answer every call, book jobs, and follow up automatically. Got 60 seconds for me to show you what that looks like for your company?",
        vm: "Hi, this is Roman from SFB Connect — we help roofers answer every call with AI and book more jobs. Call me back at (213) 495-3536.",
      },
    ],
    campaigns: [{ id: "camp-roofer-pilot", name: "Roofer Pilot", status: "active" }],
  };
}
async function getState(env) {
  const raw = await env.RIPMODE_KV.get("state");
  if (raw) return JSON.parse(raw);
  const s = seedState();
  await env.RIPMODE_KV.put("state", JSON.stringify(s));
  return s;
}
async function saveState(env, s) {
  await env.RIPMODE_KV.put("state", JSON.stringify(s));
}

async function requireSession(env, request) {
  const auth = request.headers.get("Authorization") || "";
  const m = auth.match(/^Bearer\s+(.+)$/);
  if (!m) return null;
  const h = await sha256Hex(m[1]);
  const raw = await env.RIPMODE_KV.get("sessions:" + h);
  if (!raw) return null;
  const s = JSON.parse(raw);
  if (Date.now() > s.exp) { await env.RIPMODE_KV.delete("sessions:" + h); return null; }
  return s.username;
}
async function newSession(env, username) {
  const token = crypto.randomUUID() + "-" + hex(crypto.getRandomValues(new Uint8Array(16)));
  const h = await sha256Hex(token);
  await env.RIPMODE_KV.put("sessions:" + h, JSON.stringify({
    username,
    exp: Date.now() + SESSION_DAYS * 24 * 60 * 60 * 1000,
  }));
  return token;
}

async function handleApi(request, env) {
  const url = new URL(request.url);
  let path = url.pathname;
  if (path.startsWith("/ripmode")) path = path.slice("/ripmode".length);
  if (request.method === "OPTIONS") return json({ ok: true });

  // ---- auth ----
  if (path === "/api/auth/check" && request.method === "POST") {
    const { username } = await request.json().catch(() => ({}));
    const u = String(username || "").toLowerCase();
    if (!ALLOWED_USERS.includes(u)) return json({ allowed: false, hasAccount: false });
    const raw = await env.RIPMODE_KV.get("users:" + u);
    return json({ allowed: true, hasAccount: !!raw });
  }
  if (path === "/api/auth/signup" && request.method === "POST") {
    const { username, password } = await request.json().catch(() => ({}));
    const u = String(username || "").toLowerCase();
    if (!ALLOWED_USERS.includes(u)) return err("That username is not on the team.");
    if (!password || password.length < 8) return err("Password must be at least 8 characters.");
    if (await env.RIPMODE_KV.get("users:" + u)) return err("That username already has an account — sign in instead.");
    const { salt, hash } = await hashPassword(password);
    await env.RIPMODE_KV.put("users:" + u, JSON.stringify({ salt, hash }));
    const token = await newSession(env, u);
    return json({ token, username: u });
  }
  if (path === "/api/auth/login" && request.method === "POST") {
    const { username, password } = await request.json().catch(() => ({}));
    const u = String(username || "").toLowerCase();
    if (!ALLOWED_USERS.includes(u)) return err("Invalid username or password.", 401);
    const raw = await env.RIPMODE_KV.get("users:" + u);
    if (!raw) return err("Invalid username or password.", 401);
    const { salt, hash } = JSON.parse(raw);
    const attempt = await hashPassword(password, salt);
    if (attempt.hash !== hash) return err("Invalid username or password.", 401);
    const token = await newSession(env, u);
    return json({ token, username: u });
  }
  if (path === "/api/auth/status" && request.method === "POST") {
    const username = await requireSession(env, request);
    if (!username) return err("Not signed in.", 401);
    return json({ username });
  }
  if (path === "/api/auth/logout" && request.method === "POST") {
    const auth = request.headers.get("Authorization") || "";
    const m = auth.match(/^Bearer\s+(.+)$/);
    if (m) await env.RIPMODE_KV.delete("sessions:" + await sha256Hex(m[1]));
    return json({ ok: true });
  }

  // ---- state (session required) ----
  const username = await requireSession(env, request);
  if (!username) return err("Not signed in.", 401);

  if (path === "/api/state" && request.method === "GET") {
    return json(await getState(env));
  }
  if (path === "/api/state" && request.method === "POST") {
    const body = await request.json().catch(() => ({}));
    const s = await getState(env);
    const now = new Date();
    const date = now.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
    const time = now.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" });
    const op = body.op;

    if (op === "addLead") {
      s.leads.push({
        id: "lead-" + crypto.randomUUID().slice(0, 8),
        business: String(body.business || "").slice(0, 120),
        phone: String(body.phone || "").slice(0, 40),
        niche: String(body.niche || "").slice(0, 80),
        owner: String(body.owner || "").slice(0, 80),
        email: String(body.email || "").slice(0, 120),
        city: String(body.city || "").slice(0, 80),
        stage: "New",
      });
    } else if (op === "deleteLead") {
      s.leads = s.leads.filter((l) => l.id !== body.leadId);
      s.callLogs = s.callLogs.filter((c) => c.leadId !== body.leadId);
      s.conversations = s.conversations.filter((c) => c.leadId !== body.leadId);
    } else if (op === "setStage") {
      const l = s.leads.find((x) => x.id === body.leadId);
      if (l && ["New", "In conversation", "Proposal", "Won", "Lost"].includes(body.stage)) l.stage = body.stage;
    } else if (op === "logDisposition") {
      s.callLogs.push({ id: "call-" + crypto.randomUUID().slice(0, 8), leadId: body.leadId, outcome: String(body.outcome || ""), date, time, by: username });
      if (body.stat) s.sessionStats[body.stat] = (s.sessionStats[body.stat] || 0) + 1;
      if (body.stat && body.stat !== "dials") s.sessionStats.dials = (s.sessionStats.dials || 0) + 1;
    } else if (op === "bookMeeting") {
      const l = s.leads.find((x) => x.id === body.leadId);
      s.meetings.push({
        id: "mtg-" + crypto.randomUUID().slice(0, 8),
        leadId: body.leadId,
        date: body.date || date, time: body.time || time,
        typeName: body.typeName || "30 min meeting", by: username,
      });
      s.sessionStats.meetings = (s.sessionStats.meetings || 0) + 1;
      if (l && l.stage === "New") l.stage = "In conversation";
      s.callLogs.push({ id: "call-" + crypto.randomUUID().slice(0, 8), leadId: body.leadId, outcome: "meeting_booked", date, time, by: username });
      s.followUps.push({ id: "fu-" + crypto.randomUUID().slice(0, 8), leadId: body.leadId, kind: "email", status: "queued", note: "Meeting confirmation email — queued until Resend is wired.", date, time });
      s.followUps.push({ id: "fu-" + crypto.randomUUID().slice(0, 8), leadId: body.leadId, kind: "sms", status: "pending", note: "Meeting confirmation SMS — send via Google Voice (not sent automatically).", date, time });
    } else if (op === "addMessage") {
      let conv = s.conversations.find((c) => c.leadId === body.leadId);
      if (!conv) { conv = { leadId: body.leadId, messages: [] }; s.conversations.push(conv); }
      conv.messages.push({ id: "msg-" + crypto.randomUUID().slice(0, 8), from: body.from === "lead" ? "lead" : "me", text: String(body.text || "").slice(0, 2000), date, time });
    } else {
      return err("Unknown operation.");
    }
    await saveState(env, s);
    return json(s);
  }
  return err("Not found.", 404);
}

export default {
  async fetch(request, env) {
    const incoming = new URL(request.url);
    const isApi = incoming.pathname === "/ripmode/api" || incoming.pathname.startsWith("/ripmode/api/") ||
      incoming.pathname === "/api" || incoming.pathname.startsWith("/api/");
    if (isApi) return handleApi(request, env);

const FILES = {"index.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>RIP MODE \u2014 SFB Connect Dialer</title>\n<link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n<div id=\"app\">\n  <!-- LOGIN -->\n  <div id=\"login-screen\" class=\"screen\">\n    <div class=\"login-card\">\n      <div class=\"login-brand\">SFB CONNECT</div>\n      <h1>RIP MODE</h1>\n      <p class=\"login-sub\">The dialer. Sign in to start ripping.</p>\n      <div id=\"login-error\" class=\"error hidden\"></div>\n      <label>Username\n        <input id=\"login-username\" type=\"text\" autocomplete=\"username\" placeholder=\"romanroyce\" autocapitalize=\"off\" spellcheck=\"false\">\n      </label>\n      <label>Password\n        <input id=\"login-password\" type=\"password\" autocomplete=\"current-password\" placeholder=\"Your password\">\n      </label>\n      <label id=\"confirm-wrap\" class=\"hidden\">Confirm password\n        <input id=\"login-confirm\" type=\"password\" autocomplete=\"new-password\" placeholder=\"Repeat your password\">\n      </label>\n      <button id=\"login-btn\" class=\"btn-primary\">Sign in</button>\n      <p id=\"login-hint\" class=\"login-hint\">First time signing in with a username? You will set your password (min 8 characters) and it is saved for next time.</p>\n      <p class=\"login-hint\">No email password reset. If you forget your password, your account is cleared and you sign up again.</p>\n      <p class=\"login-hint small\">Only romanroyce, loganwells and braylengarrett can sign in.</p>\n    </div>\n  </div>\n\n  <!-- DASHBOARD -->\n  <div id=\"dashboard\" class=\"screen hidden\">\n    <header class=\"topbar\">\n      <div class=\"topbar-left\">\n        <span class=\"brand\">SFB CONNECT // RIP MODE</span>\n        <span class=\"gv-badge\">Calling from Google Voice (213) 495-3536</span>\n      </div>\n      <div class=\"topbar-right\">\n        <span id=\"whoami\" class=\"whoami\"></span>\n        <button id=\"logout-btn\" class=\"btn-ghost\">Log out</button>\n      </div>\n    </header>\n    <nav class=\"tabs\">\n      <button data-tab=\"rip\" class=\"tab active\">RIP MODE</button>\n      <button data-tab=\"leads\" class=\"tab\">Leads</button>\n      <button data-tab=\"pipeline\" class=\"tab\">Pipeline</button>\n      <button data-tab=\"calendar\" class=\"tab\">Calendar</button>\n      <button data-tab=\"calllog\" class=\"tab\">Call Log</button>\n      <button data-tab=\"connections\" class=\"tab\">Connections</button>\n    </nav>\n    <main id=\"main\"></main>\n  </div>\n</div>\n<script src=\"app.js\"></script>\n</body>\n</html>\n", "app.js": "/* RIP MODE standalone \u2014 frontend.\n   API lives in the Cloudflare router worker (same origin at /ripmode/api when\n   served from sixfigureblueprints.com, workers.dev URL when on Vercel).\n   Google Voice has NO API: CALL/TEXT open Google Voice with the lead's\n   number shown \u2014 nothing here auto-dials, auto-plays a script, auto-drops\n   a voicemail, or auto-sends an SMS. */\nconst WORKER_API = \"https://sfb-ripmode-router.2romanroyce8.workers.dev/api\";\nconst API_BASE = location.hostname.includes(\"sixfigureblueprints.com\")\n  ? \"/ripmode/api\" : WORKER_API;\nconst GV_NUMBER = \"(213) 495-3536\";\nconst CAL_LINK = \"https://cal.com/roman-royce/30min\";\nconst ALLOWED_USERS = [\"romanroyce\", \"loganwells\", \"braylengarrett\"];\n\nlet token = localStorage.getItem(\"rip_token\") || \"\";\nlet me = \"\";\nlet state = null;         // shared state from KV: leads, callLogs, conversations, meetings, stats\nlet currentTab = \"rip\";\nlet ripIndex = 0;\nlet calEvent = null, calDay = null, calTime = null;\nlet activeConv = null;    // lead id for call-log conversation view\nlet micStream = null, micLevel = 0, micOn = false, muted = false;\n\nconst $ = (s) => document.querySelector(s);\nconst esc = (s) => String(s ?? \"\").replace(/[&<>\"']/g, (c) => ({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\nconst fmtPhone = (p) => p || \"\";\nconst todayStr = () => new Date().toLocaleDateString(\"en-US\", {month:\"short\", day:\"numeric\", year:\"numeric\"});\nconst nowTime = () => new Date().toLocaleTimeString(\"en-US\", {hour:\"numeric\", minute:\"2-digit\"});\n\nasync function api(path, method, body) {\n  const res = await fetch(API_BASE + path, {\n    method: method || \"GET\",\n    headers: {\"Content-Type\": \"application/json\", ...(token ? {Authorization: \"Bearer \" + token} : {})},\n    body: body ? JSON.stringify(body) : undefined,\n  });\n  const data = await res.json().catch(() => ({}));\n  if (!res.ok) throw new Error(data.error || (\"Request failed: \" + res.status));\n  return data;\n}\n\n/* ---------- auth ---------- */\nfunction showLogin(msg, isOk) {\n  $(\"#dashboard\").classList.add(\"hidden\");\n  $(\"#login-screen\").classList.remove(\"hidden\");\n  const err = $(\"#login-error\");\n  if (msg) { err.textContent = msg; err.className = isOk ? \"ok-note\" : \"error\"; }\n  else err.className = \"hidden\";\n}\nfunction showDashboard() {\n  $(\"#login-screen\").classList.add(\"hidden\");\n  $(\"#dashboard\").classList.remove(\"hidden\");\n  $(\"#whoami\").textContent = \"@\" + me;\n}\n\nasync function checkSession() {\n  if (!token) { showLogin(); return; }\n  try {\n    const r = await api(\"/auth/status\", \"POST\", {});\n    me = r.username;\n    await loadState();\n    showDashboard();\n    render();\n  } catch (e) { token = \"\"; localStorage.removeItem(\"rip_token\"); showLogin(); }\n}\n\nasync function doLogin() {\n  const username = $(\"#login-username\").value.trim().toLowerCase();\n  const password = $(\"#login-password\").value;\n  const confirm = $(\"#login-confirm\").value;\n  const err = $(\"#login-error\");\n  if (!ALLOWED_USERS.includes(username)) {\n    err.textContent = \"That username is not on the team. Only romanroyce, loganwells and braylengarrett can sign in.\";\n    err.className = \"error\"; return;\n  }\n  if (!password) { err.textContent = \"Enter a password.\"; err.className = \"error\"; return; }\n  $(\"#login-btn\").disabled = true;\n  try {\n    const status = await api(\"/auth/check\", \"POST\", {username});\n    if (!status.hasAccount) {\n      // first sign-in = signup\n      if (password.length < 8) throw new Error(\"Password must be at least 8 characters.\");\n      if (password !== confirm) throw new Error(\"Passwords do not match. Type the same password twice.\");\n      const r = await api(\"/auth/signup\", \"POST\", {username, password});\n      token = r.token; localStorage.setItem(\"rip_token\", token); me = username;\n      await loadState(); showDashboard(); render();\n      showToast(\"Account created for @\" + username + \". That password is saved \u2014 use it next time.\");\n    } else {\n      const r = await api(\"/auth/login\", \"POST\", {username, password});\n      token = r.token; localStorage.setItem(\"rip_token\", token); me = username;\n      await loadState(); showDashboard(); render();\n    }\n  } catch (e) {\n    err.textContent = e.message || \"Sign-in failed.\";\n    err.className = \"error\";\n    // if account does not exist yet, show the confirm field so first sign-in can set a password\n    try {\n      const s = await api(\"/auth/check\", \"POST\", {username});\n      if (!s.hasAccount) $(\"#confirm-wrap\").classList.remove(\"hidden\");\n    } catch (_) {}\n  } finally { $(\"#login-btn\").disabled = false; }\n}\n\nfunction logout() {\n  if (token) api(\"/auth/logout\", \"POST\", {}).catch(() => {});\n  token = \"\"; me = \"\"; localStorage.removeItem(\"rip_token\");\n  $(\"#login-password\").value = \"\"; $(\"#login-confirm\").value = \"\";\n  $(\"#confirm-wrap\").classList.add(\"hidden\");\n  showLogin();\n}\n\nasync function loadState() { state = await api(\"/state\", \"GET\"); }\nasync function mutate(op, payload) {\n  state = await api(\"/state\", \"POST\", {op, ...payload});\n  render();\n}\nfunction showToast(msg) { alert(msg); }\n\n/* ---------- shared helpers ---------- */\nfunction leadById(id) { return (state.leads || []).find((l) => l.id === id); }\nfunction callsFor(leadId) { return (state.callLogs || []).filter((c) => c.leadId === leadId); }\nfunction convFor(leadId) { return (state.conversations || []).find((c) => c.leadId === leadId); }\nfunction bumpStat(key) { state.sessionStats[key] = (state.sessionStats[key] || 0) + 1; }\n\nfunction openGoogleVoice(kind, lead) {\n  // Google Voice has no API and no prefill URL \u2014 open the right GV screen,\n  // show the number / message, and let Rome dial or send from GV itself.\n  const url = kind === \"text\"\n    ? \"https://voice.google.com/u/0/messages\"\n    : \"https://voice.google.com/u/0/calls\";\n  window.open(url, \"_blank\");\n}\n\n/* ---------- tabs ---------- */\ndocument.querySelectorAll(\".tab\").forEach((b) => {\n  b.addEventListener(\"click\", () => {\n    document.querySelectorAll(\".tab\").forEach((x) => x.classList.remove(\"active\"));\n    b.classList.add(\"active\");\n    currentTab = b.dataset.tab;\n    render();\n  });\n});\n\nfunction render() {\n  if (!state) return;\n  const main = $(\"#main\");\n  if (currentTab === \"rip\") main.innerHTML = renderRip();\n  else if (currentTab === \"leads\") main.innerHTML = renderLeads();\n  else if (currentTab === \"pipeline\") main.innerHTML = renderPipeline();\n  else if (currentTab === \"calendar\") main.innerHTML = renderCalendar();\n  else if (currentTab === \"calllog\") main.innerHTML = renderCallLog();\n  else if (currentTab === \"connections\") main.innerHTML = renderConnections();\n  bindTab();\n}\n\n/* ---------- RIP MODE ---------- */\nfunction renderRip() {\n  const leads = state.leads || [];\n  const lead = leads[ripIndex] || null;\n  if (!lead) return `<h2>RIP MODE</h2><p class=\"sub\">No leads yet. Add one in the Leads tab.</p>`;\n  const calls = callsFor(lead.id);\n  const last = calls[calls.length - 1];\n  const s = state.sessionStats || {};\n  const script = (state.scripts && state.scripts[0]) || {title: \"Roofer pitch\", body: \"Hi, this is Roman from SFB Connect \u2014 we build AI receptionists for roofers that answer every call, book jobs, and follow up automatically. Got 60 seconds for me to show you what that looks like for your company?\"};\n  return `\n  <h2>RIP MODE</h2>\n  <p class=\"sub\">Dialer \u2014 calling from Google Voice ${esc(GV_NUMBER)}. Google Voice has no API, so Call opens Google Voice with this lead's number ready \u2014 you talk, then log the outcome here.</p>\n  <div class=\"grid2\">\n    <div class=\"card\">\n      <div class=\"lead-line\">\n        <span class=\"badge\">#${ripIndex + 1} / ${leads.length}</span>\n        <div style=\"margin-top:10px\"><b>${esc(lead.business)}</b></div>\n        <div>${esc(lead.niche || \"Roofing\")}</div>\n        <div>Owner: ${esc(lead.owner || \"no name on file\")}</div>\n        <div>Phone: ${esc(lead.phone)}</div>\n        ${lead.email ? `<div>Email: ${esc(lead.email)}</div>` : `<div>Email: none on file</div>`}\n      </div>\n      ${calls.length ? `\n      <div class=\"section-title\">Last Call</div>\n      <div class=\"lead-line\">${esc(last.date)} at ${esc(last.time)} \u2014 ${esc(last.outcome)}<br>\n      Called ${calls.length} time${calls.length === 1 ? \"\" : \"s\"} total.</div>` : `\n      <div class=\"section-title\">Last Call</div>\n      <div class=\"notice\">First call \u2014 no call history yet.</div>`}\n      <div class=\"section-title\">Session Data</div>\n      <div class=\"stat-boxes\">\n        <div class=\"stat-box\"><div class=\"num\">${s.dials || 0}</div><div class=\"lbl\">Dials</div></div>\n        <div class=\"stat-box\"><div class=\"num\">${s.connected || 0}</div><div class=\"lbl\">Connected</div></div>\n        <div class=\"stat-box\"><div class=\"num\">${s.noAnswer || 0}</div><div class=\"lbl\">No Answer</div></div>\n        <div class=\"stat-box\"><div class=\"num\">${s.voicemail || 0}</div><div class=\"lbl\">Voicemail</div></div>\n        <div class=\"stat-box\"><div class=\"num\">${s.meetings || 0}</div><div class=\"lbl\">Meetings Booked</div></div>\n        <div class=\"stat-box\"><div class=\"num\">${s.perHour || 0}</div><div class=\"lbl\">Per Hour</div></div>\n      </div>\n      <div class=\"section-title\">No Contact</div>\n      <div class=\"dispo-row\">\n        <button class=\"btn\" data-dispo=\"no_answer\">No Answer</button>\n        <button class=\"btn\" data-dispo=\"voicemail\">Voicemail</button>\n      </div>\n      <div class=\"section-title\">Conversation</div>\n      <div class=\"dispo-row\">\n        <button class=\"btn\" data-dispo=\"not_interested\">Not Interested</button>\n        <button class=\"btn\" data-dispo=\"callback\">Callback</button>\n        <button class=\"btn\" data-dispo=\"receptionist\">Receptionist</button>\n        <button class=\"btn\" data-dispo=\"send_vsl\">Send VSL</button>\n      </div>\n      <div class=\"section-title\">Result</div>\n      <button class=\"btn btn-green\" id=\"book-meeting-btn\" style=\"width:100%;padding:14px;font-size:16px\">MEETING BOOKED \u2014 CONFIRM + EMAIL + SMS</button>\n      <p class=\"notice\">Confirm books the meeting and queues the follow-ups. Email sends once Resend is wired. SMS opens Google Voice with a confirmation text ready for you to send \u2014 it is not sent automatically.</p>\n      <div style=\"display:flex;gap:8px;margin-top:14px\">\n        <button class=\"btn\" id=\"prev-lead\" ${ripIndex === 0 ? \"disabled\" : \"\"}>\u2190 Prev lead</button>\n        <button class=\"btn\" id=\"next-lead\" ${ripIndex >= leads.length - 1 ? \"disabled\" : \"\"}>Next lead \u2192</button>\n      </div>\n    </div>\n    <div class=\"card\">\n      <div class=\"lead-line\"><b>${esc(lead.business)}</b></div>\n      <div class=\"mic-wrap\">\n        <span class=\"pill\" id=\"mic-pill\">${micOn ? \"Mic live\" : \"Mic off\"}</span>\n        <div class=\"mic-bar\"><div class=\"mic-fill\" id=\"mic-fill\" style=\"width:${micLevel}%\"></div></div>\n        <span class=\"pill\">${muted ? \"MUTED\" : \"LIVE\"}</span>\n      </div>\n      <div class=\"lead-line\" style=\"font-size:20px;font-weight:700\">${esc(lead.phone)}</div>\n      <div class=\"ready-row\" style=\"margin-top:12px\">\n        <button class=\"btn btn-accent\" id=\"ready-btn\" style=\"flex:1;padding:12px\">READY</button>\n        <span class=\"pill on\" id=\"ready-state\">Not ready</span>\n      </div>\n      <div style=\"display:flex;gap:8px\">\n        <button class=\"btn\" id=\"mute-btn\" style=\"flex:1\">MUTE</button>\n        <button class=\"btn\" id=\"keypad-btn\" style=\"flex:1\">KEYPAD</button>\n      </div>\n      <div style=\"display:flex;gap:8px;margin-top:8px\">\n        <button class=\"btn\" id=\"script-btn\" style=\"flex:1\">SCRIPT</button>\n        <button class=\"btn\" id=\"dropvm-btn\" style=\"flex:1\">DROP VM</button>\n      </div>\n      <div id=\"script-box\" class=\"hidden\" style=\"margin-top:10px\">\n        <div class=\"field\"><label>${esc(script.title)}</label>\n        <textarea readonly rows=\"5\">${esc(script.body)}</textarea></div>\n        <p class=\"notice\">Google Voice cannot auto-play a script or auto-drop a voicemail \u2014 read it yourself on the call, or record the voicemail in Google Voice.</p>\n      </div>\n      <div id=\"keypad-box\" class=\"hidden\" style=\"margin-top:10px\">\n        <div class=\"slots\">${[\"1\",\"2\",\"3\",\"4\",\"5\",\"6\",\"7\",\"8\",\"9\",\"*\",\"0\",\"#\"].map((k) => `<button class=\"slot\" data-key=\"${k}\">${k}</button>`).join(\"\")}</div>\n      </div>\n      <button class=\"big-call\" id=\"call-btn\">CALL</button>\n      <button class=\"btn\" id=\"text-btn\" style=\"width:100%;margin-top:8px;padding:13px\">TEXT</button>\n      <p class=\"notice\">Call opens Google Voice (calls page) \u2014 dial ${esc(lead.phone)} from ${esc(GV_NUMBER)}. Text opens Google Voice messages \u2014 send from ${esc(GV_NUMBER)}.</p>\n    </div>\n  </div>`;\n}\n\nfunction bindRip() {\n  const leads = state.leads || [];\n  const lead = leads[ripIndex];\n  if (!lead) return;\n  const prev = $(\"#prev-lead\"), next = $(\"#next-lead\");\n  if (prev) prev.onclick = () => { if (ripIndex > 0) { ripIndex--; render(); } };\n  if (next) next.onclick = () => { if (ripIndex < leads.length - 1) { ripIndex++; render(); } };\n  document.querySelectorAll(\"[data-dispo]\").forEach((b) => {\n    b.onclick = async () => {\n      const d = b.dataset.dispo;\n      const map = {no_answer: \"noAnswer\", voicemail: \"voicemail\", not_interested: \"connected\", callback: \"connected\", receptionist: \"connected\", send_vsl: \"connected\"};\n      await mutate(\"logDisposition\", {leadId: lead.id, outcome: d, stat: map[d] || \"connected\"});\n    };\n  });\n  const bookBtn = $(\"#book-meeting-btn\");\n  if (bookBtn) bookBtn.onclick = async () => {\n    const r = await mutate(\"bookMeeting\", {leadId: lead.id});\n    const m = (state.meetings || []).find((x) => x.leadId === lead.id);\n    const text = `Hi, this is Roman from SFB Connect \u2014 confirming our meeting. Here is the booking link if you need it: ${CAL_LINK}`;\n    showToast(\"Meeting booked for \" + lead.business + \". Email is queued (Resend pending). SMS: Google Voice will open with this text ready to send:\\n\\n\" + text);\n    openGoogleVoice(\"text\", lead);\n  };\n  const readyBtn = $(\"#ready-btn\");\n  if (readyBtn) readyBtn.onclick = async () => {\n    const rs = $(\"#ready-state\");\n    const on = rs.textContent !== \"Ready\";\n    rs.textContent = on ? \"Ready\" : \"Not ready\";\n    if (on) await startMic(); else stopMic();\n  };\n  const muteBtn = $(\"#mute-btn\");\n  if (muteBtn) muteBtn.onclick = () => { muted = !muted; muteBtn.textContent = muted ? \"UNMUTE\" : \"MUTE\"; render(); };\n  const keypadBtn = $(\"#keypad-btn\");\n  if (keypadBtn) keypadBtn.onclick = () => $(\"#keypad-box\").classList.toggle(\"hidden\");\n  const scriptBtn = $(\"#script-btn\");\n  if (scriptBtn) scriptBtn.onclick = () => $(\"#script-box\").classList.toggle(\"hidden\");\n  const dropVm = $(\"#dropvm-btn\");\n  if (dropVm) dropVm.onclick = () => {\n    const s = (state.scripts && state.scripts[0]) || {};\n    showToast(\"Google Voice cannot auto-drop a voicemail. Open Google Voice, call \" + lead.phone + \", and record this if it goes to voicemail:\\n\\n\" + (s.vm || \"Hi, this is Roman from SFB Connect \u2014 we help roofers answer every call with AI and book more jobs. Call me back at \" + GV_NUMBER + \".\"));\n    openGoogleVoice(\"call\", lead);\n  };\n  const callBtn = $(\"#call-btn\");\n  if (callBtn) callBtn.onclick = async () => {\n    await mutate(\"logDisposition\", {leadId: lead.id, outcome: \"dialed\", stat: \"dials\", dialOnly: true});\n    openGoogleVoice(\"call\", lead);\n  };\n  const textBtn = $(\"#text-btn\");\n  if (textBtn) textBtn.onclick = () => openGoogleVoice(\"text\", lead);\n}\n\nlet micRAF = null;\nasync function startMic() {\n  try {\n    micStream = await navigator.mediaDevices.getUserMedia({audio: true});\n    const ctx = new (window.AudioContext || window.webkitAudioContext)();\n    const src = ctx.createMediaStreamSource(micStream);\n    const an = ctx.createAnalyser(); an.fftSize = 512;\n    src.connect(an);\n    const buf = new Uint8Array(an.frequencyBinCount);\n    micOn = true;\n    const pill = $(\"#mic-pill\"); if (pill) pill.textContent = \"Mic live\";\n    const tick = () => {\n      if (!micOn) return;\n      an.getByteFrequencyData(buf);\n      const avg = buf.reduce((a, b) => a + b, 0) / buf.length;\n      micLevel = Math.min(100, Math.round(avg * 1.6));\n      const fill = $(\"#mic-fill\"); if (fill) fill.style.width = micLevel + \"%\";\n      micRAF = requestAnimationFrame(tick);\n    };\n    tick();\n  } catch (e) {\n    micOn = false;\n    const pill = $(\"#mic-pill\"); if (pill) pill.textContent = \"Mic blocked \u2014 allow microphone access in the browser\";\n    showToast(\"Microphone is not available in this browser \u2014 check the site's microphone permission. The mic bar will stay at zero.\");\n  }\n}\nfunction stopMic() {\n  micOn = false; micLevel = 0;\n  if (micRAF) cancelAnimationFrame(micRAF);\n  if (micStream) micStream.getTracks().forEach((t) => t.stop());\n  micStream = null;\n  const fill = $(\"#mic-fill\"); if (fill) fill.style.width = \"0%\";\n  const pill = $(\"#mic-pill\"); if (pill) pill.textContent = \"Mic off\";\n}\n\n/* ---------- LEADS ---------- */\nfunction renderLeads() {\n  const leads = state.leads || [];\n  return `\n  <h2>Leads</h2>\n  <p class=\"sub\">${leads.length} leads. New leads start in the Pipeline at \"New\".</p>\n  <div class=\"card\" style=\"margin-bottom:16px\">\n    <div class=\"grid2\">\n      <div class=\"field\"><label>Business name</label><input id=\"nl-business\" type=\"text\" placeholder=\"Acme Roofing\"></div>\n      <div class=\"field\"><label>Phone</label><input id=\"nl-phone\" type=\"tel\" placeholder=\"(407) 555-0100\"></div>\n      <div class=\"field\"><label>Niche / what they do</label><input id=\"nl-niche\" type=\"text\" placeholder=\"Roofing\"></div>\n      <div class=\"field\"><label>Owner name (optional)</label><input id=\"nl-owner\" type=\"text\" placeholder=\"\"></div>\n      <div class=\"field\"><label>Email (optional)</label><input id=\"nl-email\" type=\"email\" placeholder=\"\"></div>\n      <div class=\"field\"><label>City (optional)</label><input id=\"nl-city\" type=\"text\" placeholder=\"\"></div>\n    </div>\n    <button class=\"btn btn-accent\" id=\"add-lead-btn\">Add lead</button>\n    <span style=\"margin:0 8px;color:var(--muted)\">or</span>\n    <label class=\"btn\" style=\"display:inline-block\">Import CSV <input id=\"csv-input\" type=\"file\" accept=\".csv\" style=\"display:none\"></label>\n  </div>\n  <div class=\"card\"><table>\n    <thead><tr><th>#</th><th>Business</th><th>Niche</th><th>Phone</th><th>Owner</th><th>Email</th><th>Stage</th><th></th></tr></thead>\n    <tbody>${leads.map((l, i) => `<tr>\n      <td>${i + 1}</td><td><b>${esc(l.business)}</b></td><td>${esc(l.niche || \"\")}</td>\n      <td>${esc(l.phone)}</td><td>${esc(l.owner || \"no name on file\")}</td><td>${esc(l.email || \"\u2014\")}</td>\n      <td>${esc(l.stage || \"New\")}</td>\n      <td><button class=\"btn\" data-convert=\"${l.id}\">Convert to client</button>\n      <button class=\"btn btn-danger\" data-del=\"${l.id}\">Delete</button></td>\n    </tr>`).join(\"\")}</tbody>\n  </table></div>`;\n}\nfunction bindLeads() {\n  const add = $(\"#add-lead-btn\");\n  if (add) add.onclick = async () => {\n    const business = $(\"#nl-business\").value.trim();\n    const phone = $(\"#nl-phone\").value.trim();\n    if (!business || !phone) { showToast(\"Business name and phone are required.\"); return; }\n    await mutate(\"addLead\", {business, phone, niche: $(\"#nl-niche\").value.trim(), owner: $(\"#nl-owner\").value.trim(), email: $(\"#nl-email\").value.trim(), city: $(\"#nl-city\").value.trim()});\n  };\n  const csv = $(\"#csv-input\");\n  if (csv) csv.onchange = async () => {\n    const file = csv.files[0]; if (!file) return;\n    const text = await file.text();\n    const rows = text.split(/\\r?\\n/).filter(Boolean).slice(1);\n    for (const row of rows) {\n      const c = row.split(\",\").map((x) => x.trim().replace(/^\"|\"$/g, \"\"));\n      if (c[0] && c[1]) await mutate(\"addLead\", {business: c[0], phone: c[1], niche: c[2] || \"\", owner: c[3] || \"\", email: c[4] || \"\", city: c[5] || \"\"});\n    }\n    showToast(\"CSV imported.\");\n  };\n  document.querySelectorAll(\"[data-convert]\").forEach((b) => b.onclick = async () => {\n    await mutate(\"setStage\", {leadId: b.dataset.convert, stage: \"In conversation\"});\n    currentTab = \"pipeline\"; render();\n  });\n  document.querySelectorAll(\"[data-del]\").forEach((b) => b.onclick = async () => {\n    if (confirm(\"Delete this lead?\")) await mutate(\"deleteLead\", {leadId: b.dataset.del});\n  });\n}\n\n/* ---------- PIPELINE ---------- */\nconst STAGES = [\"New\", \"In conversation\", \"Proposal\", \"Won\", \"Lost\"];\nfunction renderPipeline() {\n  const leads = state.leads || [];\n  return `\n  <h2>Client Pipeline</h2>\n  <p class=\"sub\">5 stages. Move a card with the arrows or the stage picker.</p>\n  <div class=\"pipeline\">${STAGES.map((st) => `\n    <div class=\"stage-col\"><div class=\"stage-head\">${esc(st)} (${leads.filter((l) => (l.stage || \"New\") === st).length})</div>\n    ${leads.filter((l) => (l.stage || \"New\") === st).map((l) => `\n      <div class=\"pcard\"><b>${esc(l.business)}</b>\n        <div class=\"meta\">${esc(l.niche || \"\")} \u00b7 ${esc(l.phone)}</div>\n        <div class=\"meta\">${esc(l.owner || \"no name on file\")}</div>\n        <div style=\"display:flex;gap:6px;margin-top:8px\">\n          <button class=\"btn\" data-move=\"${l.id}|-1\" ${STAGES.indexOf(l.stage || \"New\") === 0 ? \"disabled\" : \"\"}>\u2190</button>\n          <select data-stagepick=\"${l.id}\" style=\"flex:1\">${STAGES.map((s) => `<option ${s === (l.stage || \"New\") ? \"selected\" : \"\"}>${s}</option>`).join(\"\")}</select>\n          <button class=\"btn\" data-move=\"${l.id}|1\" ${STAGES.indexOf(l.stage || \"New\") === STAGES.length - 1 ? \"disabled\" : \"\"}>\u2192</button>\n        </div>\n      </div>`).join(\"\") || `<div class=\"notice\">No leads here.</div>`}\n    </div>`).join(\"\")}</div>`;\n}\nfunction bindPipeline() {\n  document.querySelectorAll(\"[data-move]\").forEach((b) => b.onclick = async () => {\n    const [id, dir] = b.dataset.move.split(\"|\");\n    const l = leadById(id); if (!l) return;\n    const i = STAGES.indexOf(l.stage || \"New\") + Number(dir);\n    if (i < 0 || i >= STAGES.length) return;\n    await mutate(\"setStage\", {leadId: id, stage: STAGES[i]});\n  });\n  document.querySelectorAll(\"[data-stagepick]\").forEach((s) => s.onchange = async () => {\n    await mutate(\"setStage\", {leadId: s.dataset.stagepick, stage: s.value});\n  });\n}\n\n/* ---------- CALENDAR (Cal.com mirror) ---------- */\nconst CAL_TYPES = [\n  {id: \"15min\", name: \"15 min meeting\", desc: \"15 minutes \u00b7 Video call\", mins: 15},\n  {id: \"30min\", name: \"30 min meeting\", desc: \"30 minutes \u00b7 Video call\", mins: 30},\n  {id: \"secret\", name: \"Secret meeting\", desc: \"Private \u00b7 Video call\", mins: 30},\n  {id: \"sfb-discovery-call\", name: \"Six Figure Blueprints \u2014 Discovery Call\", desc: \"Discovery \u00b7 Video call\", mins: 30},\n  {id: \"bingled-website-strategy\", name: \"Bingled \u2014 Website Strategy Call\", desc: \"Website strategy \u00b7 Video call\", mins: 30},\n];\nconst SLOT_TIMES = [\"9:00 AM\",\"9:30 AM\",\"10:00 AM\",\"10:30 AM\",\"11:00 AM\",\"11:30 AM\",\"1:00 PM\",\"1:30 PM\",\"2:00 PM\",\"2:30 PM\",\"3:00 PM\",\"3:30 PM\",\"4:00 PM\",\"4:30 PM\"];\nfunction nextDays(n) {\n  const out = [];\n  const d = new Date();\n  while (out.length < n) { d.setDate(d.getDate() + 1); out.push(new Date(d)); }\n  return out;\n}\nfunction renderCalendar() {\n  const days = nextDays(14);\n  const meetings = state.meetings || [];\n  return `\n  <h2>Calendar</h2>\n  <p class=\"sub\">Cal.com \u2014 pick an event type, a day, and a time. Booking opens your real Cal.com link: ${esc(CAL_LINK)}</p>\n  <div class=\"cal-layout\">\n    <div>\n      <div class=\"section-title\" style=\"margin-top:0\">Event types</div>\n      ${CAL_TYPES.map((t) => `<div class=\"event-type ${calEvent === t.id ? \"sel\" : \"\"}\" data-caltype=\"${t.id}\">\n        <b>${esc(t.name)}</b><span>${esc(t.desc)}</span></div>`).join(\"\")}\n      <div class=\"card\" style=\"margin-top:16px\">\n        <div class=\"section-title\" style=\"margin-top:0\">Booked meetings</div>\n        ${meetings.length ? meetings.map((m) => {\n          const l = leadById(m.leadId);\n          return `<div class=\"kv\"><span>${esc(l ? l.business : \"Meeting\")}<br><span style=\"color:var(--muted);font-size:12px\">${esc(m.date)} \u00b7 ${esc(m.time)} \u00b7 ${esc(m.typeName || \"\")}</span></span><span class=\"badge green\">Booked</span></div>`;\n        }).join(\"\") : `<div class=\"notice\">No meetings booked yet.</div>`}\n      </div>\n    </div>\n    <div class=\"card\">\n      <h3 style=\"margin-top:0\">${esc((CAL_TYPES.find((t) => t.id === calEvent) || CAL_TYPES[1]).name)}</h3>\n      <p class=\"notice\">Times are Eastern. Pick a day, then a time, then confirm \u2014 or book directly on Cal.com.</p>\n      <div class=\"days\">${days.map((d, i) => `<button class=\"day ${calDay === i ? \"sel\" : \"\"}\" data-calday=\"${i}\">\n        <span>${d.toLocaleDateString(\"en-US\", {weekday: \"short\"})}</span><b>${d.getDate()}</b>\n        <span>${d.toLocaleDateString(\"en-US\", {month: \"short\"})}</span></button>`).join(\"\")}</div>\n      <div class=\"slots\">${SLOT_TIMES.map((t) => `<button class=\"slot ${calTime === t ? \"sel\" : \"\"}\" data-caltime=\"${t}\">${t}</button>`).join(\"\")}</div>\n      <div class=\"grid2\">\n        <div class=\"field\"><label>Book for lead</label>\n          <select id=\"cal-lead\">${(state.leads || []).map((l) => `<option value=\"${l.id}\">${esc(l.business)}</option>`).join(\"\")}</select></div>\n        <div class=\"field\"><label>Your name</label><input id=\"cal-name\" type=\"text\" value=\"Roman Royce\"></div>\n      </div>\n      <div style=\"display:flex;gap:8px;flex-wrap:wrap\">\n        <button class=\"btn btn-accent\" id=\"cal-confirm\">Confirm booking</button>\n        <button class=\"btn\" id=\"cal-open\">Book on Cal.com \u2197</button>\n      </div>\n      <p class=\"notice\">Confirm saves the meeting here and in the call log. The live Cal.com booking itself happens on cal.com \u2014 this app does not hold a Cal.com API key.</p>\n    </div>\n  </div>`;\n}\nfunction bindCalendar() {\n  document.querySelectorAll(\"[data-caltype]\").forEach((el) => el.onclick = () => { calEvent = el.dataset.caltype; render(); });\n  document.querySelectorAll(\"[data-calday]\").forEach((el) => el.onclick = () => { calDay = Number(el.dataset.calday); render(); });\n  document.querySelectorAll(\"[data-caltime]\").forEach((el) => el.onclick = () => { calTime = el.dataset.caltime; render(); });\n  const open = $(\"#cal-open\");\n  if (open) open.onclick = () => window.open(CAL_LINK, \"_blank\");\n  const confirm = $(\"#cal-confirm\");\n  if (confirm) confirm.onclick = async () => {\n    if (calDay === null || !calTime) { showToast(\"Pick a day and a time first.\"); return; }\n    const type = CAL_TYPES.find((t) => t.id === (calEvent || \"30min\")) || CAL_TYPES[1];\n    const day = nextDays(14)[calDay];\n    const date = day.toLocaleDateString(\"en-US\", {weekday: \"long\", month: \"long\", day: \"numeric\"});\n    const leadId = $(\"#cal-lead\") ? $(\"#cal-lead\").value : (state.leads[0] || {}).id;\n    await mutate(\"bookMeeting\", {leadId, date, time: calTime, typeName: type.name});\n    showToast(\"Meeting booked: \" + date + \" at \" + calTime + \" (\" + type.name + \"). Email is queued (Resend pending) \u2014 confirm on Cal.com if you want the live invite sent.\");\n  };\n}\n\n/* ---------- CALL LOG + CONVERSATIONS ---------- */\nfunction renderCallLog() {\n  const logs = [...(state.callLogs || [])].reverse();\n  const leads = state.leads || [];\n  if (activeConv) {\n    const lead = leadById(activeConv);\n    const conv = convFor(activeConv) || {messages: []};\n    const calls = callsFor(activeConv);\n    return `\n    <button class=\"btn\" id=\"back-convs\">\u2190 All conversations</button>\n    <h2 style=\"margin-top:14px\">${esc(lead ? lead.business : \"Conversation\")}</h2>\n    <p class=\"sub\">${esc(lead ? lead.phone : \"\")} \u00b7 ${calls.length} call${calls.length === 1 ? \"\" : \"s\"} logged</p>\n    <div class=\"card\"><div class=\"chat-thread\">\n      ${calls.map((c) => `<div class=\"msg in\">Call \u2014 ${esc(c.outcome)}<div class=\"mmeta\">${esc(c.date)} \u00b7 ${esc(c.time)}</div></div>`).join(\"\")}\n      ${(conv.messages || []).map((m) => `<div class=\"msg ${m.from === \"me\" ? \"out\" : \"in\"}\">${esc(m.text)}<div class=\"mmeta\">${esc(m.from === \"me\" ? \"You\" : \"Lead\")} \u00b7 ${esc(m.date || \"\")} ${esc(m.time || \"\")}</div></div>`).join(\"\") || \"\"}\n      ${!calls.length && !(conv.messages || []).length ? `<div class=\"notice\">No calls or messages yet for this lead.</div>` : \"\"}\n    </div>\n    <div class=\"chat-input\">\n      <input id=\"chat-input\" type=\"text\" placeholder=\"Type a message or note for this lead\u2026\">\n      <button class=\"btn btn-accent\" id=\"chat-send\">Send</button>\n    </div>\n    <p class=\"notice\">Messages you type here are saved to this lead's thread. Outbound texts go through Google Voice \u2014 use the TEXT button in RIP MODE to send them.</p>\n    </div>`;\n  }\n  return `\n  <h2>Call Log</h2>\n  <p class=\"sub\">Every call, mirrored as a conversation. Tap a lead to open its chat thread.</p>\n  <div class=\"grid2\">\n    <div>\n      <div class=\"section-title\" style=\"margin-top:0\">Calls</div>\n      <div class=\"card\">${logs.length ? `<table><thead><tr><th>Lead</th><th>Outcome</th><th>When</th></tr></thead><tbody>\n        ${logs.map((c) => { const l = leadById(c.leadId); return `<tr class=\"rowlink\" data-openconv=\"${c.leadId}\">\n          <td><b>${esc(l ? l.business : \"\u2014\")}</b></td><td>${esc(c.outcome)}</td><td>${esc(c.date)} ${esc(c.time)}</td></tr>`; }).join(\"\")}\n      </tbody></table>` : `<div class=\"notice\">No calls logged yet. Dial in RIP MODE and log the outcome.</div>`}</div>\n    </div>\n    <div>\n      <div class=\"section-title\" style=\"margin-top:0\">Conversations</div>\n      <div class=\"conv-list\">${leads.map((l) => {\n        const conv = convFor(l.id);\n        const lastMsg = (conv && conv.messages && conv.messages[conv.messages.length - 1]) || null;\n        const n = callsFor(l.id).length;\n        return `<button class=\"conv-item\" data-openconv=\"${l.id}\">\n          <span><b>${esc(l.business)}</b><br><span style=\"font-size:13px;color:var(--muted)\">${lastMsg ? esc(lastMsg.text.slice(0, 60)) : (n ? n + \" call\" + (n === 1 ? \"\" : \"s\") + \" logged\" : \"No calls or messages yet\")}</span></span>\n          <span class=\"badge\">${esc(l.stage || \"New\")}</span></button>`;\n      }).join(\"\")}</div>\n    </div>\n  </div>`;\n}\nfunction bindCallLog() {\n  const back = $(\"#back-convs\");\n  if (back) back.onclick = () => { activeConv = null; render(); };\n  document.querySelectorAll(\"[data-openconv]\").forEach((el) => el.onclick = () => { activeConv = el.dataset.openconv; render(); });\n  const send = $(\"#chat-send\");\n  const sendMsg = async () => {\n    const inp = $(\"#chat-input\");\n    const text = inp.value.trim();\n    if (!text) return;\n    await mutate(\"addMessage\", {leadId: activeConv, text, from: \"me\"});\n  };\n  if (send) send.onclick = sendMsg;\n  const inp = $(\"#chat-input\");\n  if (inp) inp.addEventListener(\"keydown\", (e) => { if (e.key === \"Enter\") sendMsg(); });\n}\n\n/* ---------- CONNECTIONS ---------- */\nfunction renderConnections() {\n  const rows = [\n    [\"Google Voice\", \"Connected\", \"Calling + texting from (213) 495-3536. Free. No API \u2014 calls and texts open in Google Voice.\", \"green\"],\n    [\"Cal.com\", \"Connected\", \"5 event types verified. Booking link: \" + CAL_LINK, \"green\"],\n    [\"Gmail\", \"Connected via Muse\", \"Muse connector is connected. This app does not sync Gmail itself.\", \"green\"],\n    [\"Google Calendar / Meet\", \"Connected via Muse\", \"Muse connector is connected. Meet links are created through Calendar events.\", \"green\"],\n    [\"Resend\", \"Key pending\", \"Domain sixfigureblueprintsllc.com is verified in Resend. sfbconnect.com is NOT verified and cannot send. The auto-dialer key still needs to be submitted to Muse \u2014 until then, follow-up emails are queued, never claimed as sent.\", \"amber\"],\n    [\"Twilio\", \"Not needed\", \"Dropped. Google Voice handles calling and texting for free \u2014 no Twilio upgrade, no Twilio number.\", \"\"],\n  ];\n  return `\n  <h2>Connections</h2>\n  <p class=\"sub\">Honest status \u2014 nothing here is marked connected unless it was verified.</p>\n  <div class=\"card\">${rows.map(([name, status, note, cls]) => `\n    <div class=\"kv\"><span><b>${esc(name)}</b><br><span style=\"color:var(--muted);font-size:13px\">${esc(note)}</span></span>\n    <span class=\"badge ${cls}\">${esc(status)}</span></div>`).join(\"\")}</div>`;\n}\n\n/* ---------- bind + init ---------- */\nfunction bindTab() {\n  if (currentTab === \"rip\") bindRip();\n  else if (currentTab === \"leads\") bindLeads();\n  else if (currentTab === \"pipeline\") bindPipeline();\n  else if (currentTab === \"calendar\") bindCalendar();\n  else if (currentTab === \"calllog\") bindCallLog();\n}\n\n$(\"#login-btn\").addEventListener(\"click\", doLogin);\n$(\"#login-password\").addEventListener(\"keydown\", (e) => { if (e.key === \"Enter\") doLogin(); });\n$(\"#login-username\").addEventListener(\"keydown\", (e) => { if (e.key === \"Enter\") doLogin(); });\n$(\"#login-username\").addEventListener(\"input\", async (e) => {\n  const u = e.target.value.trim().toLowerCase();\n  if (ALLOWED_USERS.includes(u)) {\n    try {\n      const s = await api(\"/auth/check\", \"POST\", {username: u});\n      $(\"#confirm-wrap\").classList.toggle(\"hidden\", s.hasAccount);\n      $(\"#login-hint\").textContent = s.hasAccount\n        ? \"Welcome back \u2014 enter your password.\"\n        : \"First time for this username \u2014 set a password (min 8 characters) and it will be saved for next time.\";\n    } catch (_) {}\n  }\n});\n$(\"#logout-btn\").addEventListener(\"click\", logout);\n\ncheckSession();\n", "style.css": ":root{\n  --bg:#0b0b0d; --panel:#141419; --panel2:#1c1c22; --line:#26262e;\n  --text:#f2f2f4; --muted:#9a9aa5; --accent:#ff5a1f; --green:#22c55e;\n  --red:#ef4444; --amber:#f59e0b; --blue:#3b82f6;\n}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,Helvetica,Arial,sans-serif}\n.hidden{display:none!important}\n.screen{min-height:100vh}\nbutton{cursor:pointer;font-family:inherit}\ninput,select,textarea{font-family:inherit}\n\n/* login */\n#login-screen{display:flex;align-items:center;justify-content:center;padding:24px}\n.login-card{width:100%;max-width:400px;background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:32px 28px}\n.login-brand{color:var(--accent);font-weight:800;letter-spacing:.14em;font-size:13px}\n.login-card h1{font-size:34px;margin:8px 0 4px}\n.login-sub{color:var(--muted);margin:0 0 20px}\n.login-card label{display:block;font-size:13px;color:var(--muted);margin-bottom:14px}\n.login-card input{width:100%;margin-top:6px;background:var(--panel2);border:1px solid var(--line);border-radius:10px;color:var(--text);padding:12px;font-size:16px}\n.login-card input:focus{outline:2px solid var(--accent);border-color:transparent}\n.btn-primary{width:100%;background:var(--accent);color:#fff;border:0;border-radius:10px;padding:13px;font-size:16px;font-weight:700}\n.btn-primary:disabled{opacity:.6}\n.login-hint{color:var(--muted);font-size:13px;line-height:1.5}\n.login-hint.small{font-size:12px}\n.error{background:#3a1414;border:1px solid var(--red);color:#fca5a5;border-radius:10px;padding:10px 12px;font-size:14px;margin-bottom:14px}\n.ok-note{background:#0f2e1a;border:1px solid var(--green);color:#86efac;border-radius:10px;padding:10px 12px;font-size:14px;margin-bottom:14px}\n\n/* topbar + tabs */\n.topbar{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:14px 20px;border-bottom:1px solid var(--line);flex-wrap:wrap}\n.brand{font-weight:800;letter-spacing:.08em}\n.gv-badge{font-size:12px;color:var(--muted);border:1px solid var(--line);border-radius:99px;padding:5px 10px;margin-left:10px;white-space:nowrap}\n.whoami{color:var(--muted);font-size:14px}\n.btn-ghost{background:transparent;color:var(--text);border:1px solid var(--line);border-radius:8px;padding:8px 12px}\n.tabs{display:flex;gap:4px;padding:10px 20px;border-bottom:1px solid var(--line);overflow-x:auto}\n.tab{background:transparent;color:var(--muted);border:0;border-bottom:2px solid transparent;padding:10px 14px;font-size:15px;font-weight:600;white-space:nowrap}\n.tab.active{color:var(--text);border-bottom-color:var(--accent)}\n#main{padding:20px;max-width:1200px;margin:0 auto}\nh2{margin:0 0 4px;font-size:22px}\n.sub{color:var(--muted);margin:0 0 18px;font-size:14px}\n\n/* generic */\n.card{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:16px}\n.btn{background:var(--panel2);color:var(--text);border:1px solid var(--line);border-radius:10px;padding:10px 14px;font-size:14px;font-weight:600}\n.btn:hover{border-color:var(--muted)}\n.btn-accent{background:var(--accent);border-color:var(--accent);color:#fff}\n.btn-green{background:var(--green);border-color:var(--green);color:#04150a}\n.btn-danger{background:transparent;border-color:var(--red);color:#fca5a5}\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px}\n@media(max-width:820px){.grid2{grid-template-columns:1fr}}\n.stat-boxes{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:14px 0}\n.stat-box{background:var(--panel2);border:1px solid var(--line);border-radius:12px;padding:12px;text-align:center}\n.stat-box .num{font-size:26px;font-weight:800}\n.stat-box .lbl{font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em}\n.dispo-row{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0}\n.section-title{font-size:13px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);margin:18px 0 8px}\n.lead-line{font-size:15px;line-height:1.6}\n.lead-line b{font-size:18px}\n.mic-wrap{display:flex;align-items:center;gap:10px;margin:10px 0}\n.mic-bar{flex:1;height:10px;background:var(--panel2);border-radius:99px;overflow:hidden}\n.mic-fill{height:100%;width:0%;background:var(--green);transition:width .1s}\n.big-call{width:100%;padding:16px;font-size:19px;font-weight:800;border-radius:12px;border:0;background:var(--green);color:#04150a;margin-top:10px}\n.big-call:disabled{opacity:.5}\n.ready-row{display:flex;gap:10px;align-items:center;margin-bottom:10px}\n.pill{border:1px solid var(--line);border-radius:99px;padding:6px 12px;font-size:13px;color:var(--muted)}\n.pill.on{border-color:var(--green);color:var(--green)}\ninput[type=text],input[type=email],input[type=tel],select,textarea{background:var(--panel2);border:1px solid var(--line);border-radius:10px;color:var(--text);padding:11px 12px;font-size:15px;width:100%}\ntextarea{min-height:80px;resize:vertical}\n.field{margin-bottom:12px}\n.field label{display:block;font-size:13px;color:var(--muted);margin-bottom:5px}\ntable{width:100%;border-collapse:collapse;font-size:14px}\nth,td{text-align:left;padding:10px 8px;border-bottom:1px solid var(--line)}\nth{color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.06em}\n.rowlink{cursor:pointer}\n.rowlink:hover td{background:var(--panel2)}\n.stage-col{display:flex;flex-direction:column;gap:10px;min-width:200px}\n.pipeline{display:flex;gap:12px;overflow-x:auto;padding-bottom:8px}\n.stage-head{font-weight:700;font-size:13px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}\n.pcard{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:12px}\n.pcard b{display:block;margin-bottom:4px}\n.pcard .meta{font-size:13px;color:var(--muted)}\n.cal-layout{display:grid;grid-template-columns:280px 1fr;gap:16px}\n@media(max-width:820px){.cal-layout{grid-template-columns:1fr}}\n.event-type{padding:12px;border:1px solid var(--line);border-radius:12px;margin-bottom:10px;cursor:pointer;background:var(--panel)}\n.event-type.sel{border-color:var(--accent);background:#241610}\n.event-type b{display:block}\n.event-type span{font-size:13px;color:var(--muted)}\n.days{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}\n.day{border:1px solid var(--line);border-radius:10px;padding:10px 12px;background:var(--panel);text-align:center;min-width:64px}\n.day.sel{border-color:var(--accent);background:#241610}\n.day b{display:block;font-size:16px}\n.day span{font-size:12px;color:var(--muted)}\n.slots{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}\n.slot{border:1px solid var(--line);border-radius:10px;padding:10px 14px;background:var(--panel)}\n.slot.sel{border-color:var(--accent);background:#241610}\n.chat-thread{display:flex;flex-direction:column;gap:10px}\n.msg{max-width:80%;padding:10px 14px;border-radius:14px;font-size:14px;line-height:1.5}\n.msg.in{background:var(--panel2);align-self:flex-start}\n.msg.out{background:var(--accent);color:#fff;align-self:flex-end}\n.msg .mmeta{font-size:11px;opacity:.7;margin-top:4px}\n.chat-input{display:flex;gap:8px;margin-top:14px}\n.chat-input input{flex:1}\n.conv-list{display:flex;flex-direction:column;gap:8px}\n.conv-item{display:flex;justify-content:space-between;gap:10px;padding:12px;border:1px solid var(--line);border-radius:12px;background:var(--panel);cursor:pointer;text-align:left;color:var(--text);width:100%}\n.conv-item:hover{border-color:var(--muted)}\n.badge{display:inline-block;font-size:11px;font-weight:700;padding:3px 8px;border-radius:99px;background:var(--panel2);border:1px solid var(--line);color:var(--muted)}\n.badge.green{color:var(--green);border-color:var(--green)}\n.badge.amber{color:var(--amber);border-color:var(--amber)}\n.notice{font-size:13px;color:var(--muted);line-height:1.6}\n.kv{display:flex;justify-content:space-between;gap:10px;padding:10px 0;border-bottom:1px solid var(--line);font-size:14px}\n.kv:last-child{border-bottom:0}\n"};

    // Serve the app itself from embedded files (no Vercel needed).
    let name = "index.html";
    if (incoming.pathname === "/ripmode/app.js" || incoming.pathname === "/app.js") name = "app.js";
    else if (incoming.pathname === "/ripmode/style.css" || incoming.pathname === "/style.css") name = "style.css";
    return new Response(FILES[name], {
      headers: {
        "Content-Type": {"index.html": "text/html; charset=utf-8", "app.js": "text/javascript; charset=utf-8", "style.css": "text/css; charset=utf-8"}[name],
        "Cache-Control": "no-cache",
      },
    });
  },
};
